contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint v, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= v);

        uint balBefore = address(c).balance;
        bool reverted;
        c.sendMoney(address(this), v, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(c).balance;

        assert(reverted ? balAfter == balBefore : balBefore - balAfter == v);
    }
}

