// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v, bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sendMoney(address(this), v, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        assertTrue(reverted ? balAfter == balBefore : balBefore - balAfter == v);
    }

    function testFuzz_run(uint256 v, bytes memory data) public {
        _run(v, data);
    }

    receive() external payable {}
}
